#include <stdio.h>
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    for (int i = 0; i < n; i++) {
        if (i == 0) {
            for (int x = 1; x <= n; x++) putchar('A' + x - 1);
        } else {
            for (int x = 1; x < n - i; x++) putchar('A' + x - 1);
            for (int x = n; x >= n - i; x--) putchar('A' + x - 1);
        }
        putchar('\n');
    }
    return 0;
}

