import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int n = sc.nextInt();
            for (int i = 0; i < n; i++) {
                StringBuilder sb = new StringBuilder();
                if (i == 0) {
                    for (int x = 1; x <= n; x++) sb.append((char)('A' + x - 1));
                } else {
                    for (int x = 1; x < n - i; x++) sb.append((char)('A' + x - 1));
                    for (int x = n; x >= n - i; x--) sb.append((char)('A' + x - 1));
                }
                System.out.println(sb.toString());
            }
        }
    }
}

